PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('DOM','Inspector','Mantención')));
CREATE TABLE IF NOT EXISTS bridges(id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, location TEXT NOT NULL, criticality TEXT NOT NULL CHECK(criticality IN ('Baja','Media','Alta')), simulated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS components(id INTEGER PRIMARY KEY, bridge_id INTEGER NOT NULL REFERENCES bridges(id), name TEXT NOT NULL, UNIQUE(bridge_id,name));
CREATE TABLE IF NOT EXISTS sensors(id INTEGER PRIMARY KEY, component_id INTEGER NOT NULL REFERENCES components(id), code TEXT UNIQUE NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('vibracion','inclinacion')), unit TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS measurements(id INTEGER PRIMARY KEY, sensor_id INTEGER NOT NULL REFERENCES sensors(id), value REAL, unit TEXT NOT NULL, measured_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('valido','invalido','no_disponible')), simulated INTEGER NOT NULL, external_id TEXT UNIQUE, author_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY, bridge_id INTEGER NOT NULL REFERENCES bridges(id), component_id INTEGER NOT NULL REFERENCES components(id), inspected_at TEXT NOT NULL, inspector_id INTEGER NOT NULL REFERENCES users(id), condition TEXT NOT NULL CHECK(condition IN ('Buena','Regular','Mala','Crítica')), description TEXT NOT NULL, simulated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS photos(id INTEGER PRIMARY KEY, inspection_id INTEGER NOT NULL REFERENCES inspections(id), filename TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS rules(id INTEGER PRIMARY KEY, bridge_id INTEGER NOT NULL REFERENCES bridges(id), kind TEXT NOT NULL CHECK(kind IN ('vibracion','inclinacion','visual')), threshold REAL, condition TEXT, label TEXT NOT NULL, simulated INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, author_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY, bridge_id INTEGER NOT NULL REFERENCES bridges(id), rule_id INTEGER NOT NULL REFERENCES rules(id), measurement_id INTEGER REFERENCES measurements(id), inspection_id INTEGER REFERENCES inspections(id), created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Activa' CHECK(status IN ('Activa','En atención','Resuelta')), simulated INTEGER NOT NULL, UNIQUE(rule_id,measurement_id), UNIQUE(rule_id,inspection_id));
CREATE TABLE IF NOT EXISTS alert_notes(id INTEGER PRIMARY KEY, alert_id INTEGER NOT NULL REFERENCES alerts(id), author_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, note TEXT NOT NULL, inspection_id INTEGER REFERENCES inspections(id));
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY, bridge_id INTEGER NOT NULL REFERENCES bridges(id), component_id INTEGER REFERENCES components(id), alert_id INTEGER REFERENCES alerts(id), description TEXT NOT NULL, assignee_id INTEGER NOT NULL REFERENCES users(id), planned_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pendiente' CHECK(status IN ('Pendiente','En ejecución','Completada')), author_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, author TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS measurement_history ON measurements(sensor_id,measured_at DESC);
CREATE INDEX IF NOT EXISTS alerts_bridge ON alerts(bridge_id,status);
